BERLIN = ZoneInfo("Europe/Berlin")


@pytest.fixture
def event_schedule(event, user):
    return ScheduledEventExport.objects.create(
        event=event,
        owner=user,
        export_identifier='orderlist',
        export_form_data={},
        locale='en',
        mail_subject='Export',
        mail_template='Body',
        schedule_rrule='DTSTART:20230119T000000\nRRULE:FREQ=DAILY',
        schedule_rrule_time=time(3, 30),
        schedule_next_run=datetime(2023, 3, 1, 3, 30, tzinfo=BERLIN),
    )


@pytest.fixture
def organizer_schedule(event, user):
    return ScheduledOrganizerExport.objects.create(
        organizer=event.organizer,
        owner=user,
        export_identifier='orderlist',
        export_form_data={},
        locale='en',
        mail_subject='Export',
        mail_template='Body',
        schedule_rrule='DTSTART:20230119T000000\nRRULE:FREQ=DAILY',
        schedule_rrule_time=time(3, 30),
        schedule_next_run=datetime(2023, 3, 1, 3, 30, tzinfo=BERLIN),
        timezone='Europe/Berlin',
    )


@pytest.mark.django_db
@freeze_time("2023-03-01 12:00:00")
def test_scheduled_event_export_due_is_dispatched(event, event_schedule):
    with mock.patch.object(scheduled_event_export, 'apply_async') as apply_async:
        run_scheduled_exports(None)

    apply_async.assert_called_once_with(kwargs={'event': event.pk, 'schedule': event_schedule.pk})
    event_schedule.refresh_from_db()
    assert event_schedule.schedule_next_run == datetime(2023, 3, 2, 3, 30, tzinfo=BERLIN)


@pytest.mark.django_db
@freeze_time("2023-03-01 12:00:00")
def test_scheduled_organizer_export_due_is_dispatched(event, organizer_schedule):
    with mock.patch.object(scheduled_organizer_export, 'apply_async') as apply_async:
        run_scheduled_exports(None)

    apply_async.assert_called_once_with(
        kwargs={'organizer': event.organizer.pk, 'schedule': organizer_schedule.pk}
    )
    organizer_schedule.refresh_from_db()
    assert organizer_schedule.schedule_next_run == datetime(2023, 3, 2, 3, 30, tzinfo=BERLIN)


@pytest.mark.django_db
@freeze_time("2023-03-01 12:00:00")
def test_event_and_organizer_exports_both_dispatched(event, event_schedule, organizer_schedule):
    with mock.patch.object(scheduled_event_export, 'apply_async') as event_apply_async, \
            mock.patch.object(scheduled_organizer_export, 'apply_async') as organizer_apply_async:
