@pytest.mark.django_db
@freeze_time("2023-03-01 12:00:00")
def test_not_yet_due_export_is_not_dispatched(event, event_schedule, organizer_schedule):
    event_schedule.schedule_next_run = datetime(2023, 3, 1, 18, 0, tzinfo=BERLIN)
    event_schedule.save(update_fields=['schedule_next_run'])
    organizer_schedule.schedule_next_run = datetime(2023, 3, 1, 18, 0, tzinfo=BERLIN)
    organizer_schedule.save(update_fields=['schedule_next_run'])

    with mock.patch.object(scheduled_event_export, 'apply_async') as event_apply_async, \
